## 7.9 — `backend/src/services/auth.service.ts`

```ts
import bcrypt from 'bcryptjs';
import db from '../config/db';
import AppError from '../utils/AppError';
import {
  generateAccessToken,
  generateRefreshToken,
} from '../utils/generateToken';

type RegisterInput = {
  fullName: string;
  email: string;
  phone: string;
  password: string;
};

type LoginInput = {
  email: string;
  password: string;
};

// ============ REGISTER ============
export const register = async (data: RegisterInput) => {
  // 1. Cek apakah email sudah terdaftar
  const existing = await db.candidate.findUnique({
    where: { email: data.email },
  });

  if (existing) {
    throw new AppError('Email sudah terdaftar', 409);
  }

  // 2. Hash password (10 = salt rounds)
  const passwordHash = await bcrypt.hash(data.password, 10);

  // 3. Simpan kandidat ke database
  const candidate = await db.candidate.create({
    data: {
      fullName: data.fullName,
      email: data.email,
      phone: data.phone,
      passwordHash,
    },
  });

  // 4. Terbitkan token
  const payload = { id: candidate.id, role: 'candidate' };
  const accessToken = generateAccessToken(payload);
  const refreshToken = generateRefreshToken(payload);

  return { candidate, accessToken, refreshToken };
};

// ============ LOGIN ============
export const login = async (data: LoginInput) => {
  const candidate = await db.candidate.findUnique({
    where: { email: data.email },
  });

  // Pesan & status SAMA untuk email tak ditemukan / password salah
  // → penyerang tidak bisa menebak mana yang salah
  if (!candidate) {
    throw new AppError('Email atau password salah', 401);
  }

  const isPasswordValid = await bcrypt.compare(
    data.password,
    candidate.passwordHash
  );

  if (!isPasswordValid) {
    throw new AppError('Email atau password salah', 401);
  }

  const payload = { id: candidate.id, role: 'candidate' };
  const accessToken = generateAccessToken(payload);
  const refreshToken = generateRefreshToken(payload);

  return { candidate, accessToken, refreshToken };
};
```

