## 7.10 — `backend/src/controllers/auth.controller.ts`

```ts
import { Request, Response } from 'express';
import catchAsync from '../utils/catchAsync';
import * as authService from '../services/auth.service';

const REFRESH_TOKEN_MAX_AGE = 7 * 24 * 60 * 60 * 1000; // 7 hari (ms)

// Helper kecil: set refresh token sebagai cookie httpOnly
const setRefreshTokenCookie = (res: Response, refreshToken: string) => {
  res.cookie('refreshToken', refreshToken, {
    httpOnly: true, // tidak bisa dibaca JavaScript browser → tahan XSS
    sameSite: 'lax', // perlindungan dasar CSRF
    maxAge: REFRESH_TOKEN_MAX_AGE,
  });
};

export const register = catchAsync(async (req: Request, res: Response) => {
  const { candidate, accessToken, refreshToken } =
    await authService.register(req.body);

  setRefreshTokenCookie(res, refreshToken);

  // Buang passwordHash sebelum dikirim ke client
  const { passwordHash: _ph, ...candidateSafe } = candidate;

  res.status(201).json({
    success: true,
    message: 'Registrasi berhasil',
    data: { candidate: candidateSafe, accessToken },
  });
});

export const login = catchAsync(async (req: Request, res: Response) => {
  const { candidate, accessToken, refreshToken } =
    await authService.login(req.body);

  setRefreshTokenCookie(res, refreshToken);

  const { passwordHash: _ph, ...candidateSafe } = candidate;

  res.status(200).json({
    success: true,
    message: 'Login berhasil',
    data: { candidate: candidateSafe, accessToken },
  });
});
```

